@spec cmgr_manifest_spec  src=tests/specs/cmgr_manifest_spec.lua  loc=141  cases=9

# Intent
  The manifest declares each command once, in the order it reads, carrying its
  label and its keys as binding tokens. Pins that install parses those tokens
  into the declaring scope's keymap, that a keyless entry binds nothing, that
  declaration order survives, that a name declared twice raises, that a token
  which does not parse raises, and that the load-time audit raises in both
  directions, and on a scope that registers a command while declaring no
  manifest at all.

# Helpers
  @fn fresh()  @ 16
  @fn noop()  @ 18

# Cases
  @case 'install parses each entry\'s tokens into its own scope\'s keymap'  [pure]  @ 22-34
  @case 'an entry with no keys binds nothing'  [pure]  @ 38-44
  @case 'the scope is a list, so declaration order survives install'  [pure]  @ 48-60
  @case 'a token that does not parse raises, naming the command'  [pure]  @ 64-75
  @case 'a command declared by two scopes raises at install'  [pure]  @ 79-90
  @case 'audit is quiet when entries and registrations correspond'  [pure]  @ 94-104
  @case 'audit raises on a scope that registers but declares no manifest'  [pure]  @ 108-116
  @case 'audit raises on an entry no scope registers'  [pure]  @ 120-127
  @case 'audit raises on a registered command its scope does not declare'  [pure]  @ 131-139

